import dspy
from dspy.utils.dummies import DummyLM

class LM(DummyLM):
    def __init__(self):
        super().__init__([{'answer': 'worked'}], adapter=dspy.JSONAdapter())
        self.formats = []
    @property
    def supported_params(self):
        return {'response_format'}
    @property
    def supports_response_schema(self):
        return True
    def forward(self, prompt=None, messages=None, **kwargs):
        self.formats.append(kwargs.get('response_format'))
        if len(self.formats) == 1:
            raise RuntimeError('structured output failed')
        return super().forward(prompt=prompt, messages=messages, **kwargs)

lm = LM()
with dspy.context(lm=lm, adapter=dspy.JSONAdapter()):
    out = dspy.Predict('q -> answer')(q='x')

assert hasattr(lm.formats[0], 'model_json_schema')
assert lm.formats[1] == {'type': 'json_object'}
assert out.answer == 'worked'
print(type(lm.formats[0]).__name__)
print(lm.formats[1])
print(out.answer)
